function UIAccusationMainDialog:InitHandler()
    ---@type AccusationComponent
    self._comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.AccusationComponent)
    SetButtonAction(self.EmptyClose, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnCloseHandler))
    ---@type AccusationChooseTypeNode
    self._chooseCtrl = CfUtils.GetLuaScr(self.ReportContentNode, "Game.UI.Accusation.AccusationChooseTypeNode")
    ---@type AccusationFillDetailsNode
    self._detailsCtrl = CfUtils.GetLuaScr(self.ReportingDetailsNode, "Game.UI.Accusation.AccusationFillDetailsNode")
    self.events["SHOW_ACCUSATION_PAGE"] = Events.AddListener("SHOW_ACCUSATION_PAGE", Bind(self, self.ShowPageContent))
end
