--region private
function UIAccusationMainDialog:ShowPageContent(state)
    if state == Constants.PAGE_STATES.CHOOSE_TYPE then
        self._chooseCtrl:ShowMe(self.chatEnter)
        self._detailsCtrl:HideMe()
    elseif state == Constants.PAGE_STATES.FILL_DETAILS then
        self._chooseCtrl:HideMe()
        self._detailsCtrl:ShowMe(self._targetPlayerId, self.message)
    end
end
